precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant { vec4 tint; };
#define TAU 6.28318530718
float hash21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float vnoise(vec2 p){ vec2 i=floor(p),f=fract(p); vec2 u=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1,0)),u.x),mix(hash21(i+vec2(0,1)),hash21(i+vec2(1,1)),u.x),u.y); }
float fbm(vec2 p){ float v=0.0,a=0.5; for(int i=0;i<5;i++){v+=a*vnoise(p);p*=2.0;a*=0.5;} return v; }
vec3 ACES(vec3 x){ const float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14; return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.0,1.0); }
vec3 starLayer(vec2 suv, float scale, float t){
  vec2 p = suv * scale;
  vec2 cell = floor(p);
  vec2 f = fract(p) - 0.5;
  float h = hash21(cell);
  float present = step(0.62, h);
  vec2 sp = (vec2(hash21(cell + 1.7), hash21(cell + 9.1)) - 0.5) * 0.7;
  vec2 d = f - sp;
  float r = length(d);
  float tw = 0.45 + 0.55 * sin(t * (1.5 + 2.5 * hash21(cell + 3.3)) + h * TAU);
  float core = smoothstep(0.16, 0.0, r) * (0.35 + 0.65 * tw);
  float cross = (smoothstep(0.02, 0.0, abs(d.x)) * smoothstep(0.34, 0.0, abs(d.y))
               + smoothstep(0.02, 0.0, abs(d.y)) * smoothstep(0.34, 0.0, abs(d.x))) * tw * 0.32;
  float bright = core + cross;
  float ch = hash21(cell + 5.9);
  vec3 sc = ch < 0.55 ? vec3(1.0, 0.98, 0.94)
          : ch < 0.78 ? vec3(0.78, 0.86, 1.0)
          : ch < 0.92 ? vec3(1.0, 0.86, 0.62)
                      : vec3(1.0, 0.72, 0.86);
  return sc * bright * present;
}
vec4 frag () {
  vec2 uv = uv0;
  vec2 q = uv * 2.0 - 1.0; q.y *= 1.779;
  float t = cc_time.x;
  vec2 w = q * 1.25;
  w += 0.55 * vec2(fbm(q + t * 0.025), fbm(q + 5.0 - t * 0.02));
  float n  = fbm(w + t * 0.015);
  float n2 = fbm(w * 1.9 - t * 0.012);
  vec3 deep    = vec3(0.04, 0.035, 0.11);
  vec3 indigo  = vec3(0.16, 0.12, 0.34);
  vec3 violet  = vec3(0.40, 0.22, 0.60);
  vec3 magenta = vec3(0.74, 0.30, 0.62);
  vec3 teal    = vec3(0.16, 0.48, 0.58);
  vec3 col = mix(deep, indigo, smoothstep(0.0, 0.5, n));
  col = mix(col, violet, smoothstep(0.34, 0.74, n));
  col = mix(col, magenta, smoothstep(0.62, 0.96, n) * 0.65);
  col = mix(col, teal, smoothstep(0.60, 0.95, n2) * 0.22);
  col += vec3(1.0, 0.70, 0.55) * 0.10 * smoothstep(0.9, 0.0, length(q - vec2(0.40 * sin(t * 0.05), 0.45 + 0.15 * sin(t * 0.04))));
  col += magenta * 0.10 * smoothstep(1.0, 0.0, length(q - vec2(-0.5 + 0.2 * sin(t * 0.03), -0.5)));
  vec2 suv = vec2(uv.x, uv.y * 1.779);
  vec3 stars = starLayer(suv, 22.0, t)
             + starLayer(suv + 3.1, 40.0, t) * 0.8
             + starLayer(suv + 7.7, 70.0, t) * 0.55;
  col += stars;
  col *= smoothstep(2.25, 0.35, length(q));
  col *= 1.0 - 0.38 * smoothstep(0.70, 1.0, abs(uv.y - 0.5) * 2.0);
  col = ACES(col * 1.15) * tint.rgb;
  return vec4(col, 1.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

